$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$script=Join-Path $root 'prepare-report-intervention.ps1';$tmp=Join-Path $env:TEMP ('flcad-report-int-'+[guid]::NewGuid().ToString('N'));$pub=Join-Path $tmp 'public';$out=Join-Path $tmp 'out';New-Item -ItemType Directory -Force $pub,$out|Out-Null
function W($p,$o){$o|ConvertTo-Json -Depth 10|Set-Content $p -Encoding UTF8};function Hash-File($p){(Get-FileHash $p -Algorithm SHA256).Hash.ToLowerInvariant()};function A([bool]$c,[string]$m){if(!$c){throw "ASSERTION FAILED: $m"}}
$work=(Resolve-Path (Join-Path $root '..\..')).Path;$branch=(git -C $work branch --show-current).Trim();$head=(git -C $work rev-parse HEAD).Trim();$report=[ordered]@{schema_version='1.0';task_id='REPORT-INT-DEMO';lifecycle_status='prepared-for-publication';branch=$branch;head=$head;objective='safe';acceptance_criteria=@('review');execution_status='completed';tests=@{passed=@('local');failed=@();not_run=@()};duration_ms=1;files_changed=@();limitations=@('demo');evidence=@();next_step='review'};$rp=Join-Path $pub 'report.json';W $rp $report;$review=[ordered]@{schema_version='1.0';task_id='REPORT-INT-DEMO';report_sha256=(Hash-File $rp);analyzed_commit=$head;decision='HUMAN_REVIEW_REQUIRED';reviewer='pending';findings=@();required_actions=@()};$rv=Join-Path $pub 'review-request.json';W $rv $review;$man=[ordered]@{schema_version='1.0';task_id='REPORT-INT-DEMO';version=1;manifest_scope='public';files=@([ordered]@{name='report.json';bytes=(Get-Item $rp).Length;sha256=(Hash-File $rp)},[ordered]@{name='review-request.json';bytes=(Get-Item $rv).Length;sha256=(Hash-File $rv)});integrity='sha256'};W (Join-Path $pub 'manifest.json') $man
$classification=Join-Path $tmp 'classification.json';W $classification ([ordered]@{schema_version='1.0';task_id='REPORT-INT-DEMO';classification='WAITING_FOR_USER';notification_required=$true;event='USER_APPROVAL_REQUIRED';reason='approval required';action_requested='Review report'})
try{$args=@('-NoProfile','-ExecutionPolicy','Bypass','-File',$script,'-ReportRoot',$pub,'-TaskId','REPORT-INT-DEMO','-Version','1','-ReportUrl','https://github.com/Fabio-Licht/FLCAD-Platform/blob/automation/reports/reports/REPORT-INT-DEMO/v1/report.json','-Classification',$classification,'-Worktree',$work,'-OutDir',$out);$first=& powershell @args|ConvertFrom-Json;A($first.status-eq'prepared-for-publication')'intervention prepared';$obj=Get-Content (Join-Path $out 'REPORT-INT-DEMO.v1.USER_APPROVAL_REQUIRED.json')-Raw|ConvertFrom-Json;A($obj.report_sha256-eq(Hash-File $rp)-and$obj.report_version-eq1)'binding fields';$second=& powershell @args|ConvertFrom-Json;A($second.status-eq'deduplicated')'replay dedup';$old=$ErrorActionPreference;$ErrorActionPreference='Continue';$bad=$args.Clone();$bad[$bad.IndexOf('https://github.com/Fabio-Licht/FLCAD-Platform/blob/automation/reports/reports/REPORT-INT-DEMO/v1/report.json')]='https://github.com/Fabio-Licht/FLCAD-Platform/blob/automation/reports/reports/OTHER/v1/report.json';& powershell @bad 2>&1|Out-Null;$code=$LASTEXITCODE;$ErrorActionPreference=$old;A($code-ne0)'bad URL reject';$old=$ErrorActionPreference;$ErrorActionPreference='Continue';$bad=$args.Clone();$bad[$bad.IndexOf('REPORT-INT-DEMO')]='MISSING-REPORT';& powershell @bad 2>&1|Out-Null;$code=$LASTEXITCODE;$ErrorActionPreference=$old;A($code-ne0)'missing report reject';Write-Output 'report-intervention.tests.ps1: PASS'}finally{Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue}
